ALTER TABLE public.affaires ADD COLUMN IF NOT EXISTS ca_estime_ht numeric;
ALTER TABLE public.affaires ADD COLUMN IF NOT EXISTS opportunite_source jsonb;
ALTER TABLE public.affaires ADD COLUMN IF NOT EXISTS client_contact_id uuid REFERENCES public.client_contacts(id);
CREATE OR REPLACE FUNCTION public.app_assert_affaire_write(_id uuid,_cap text) RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE a public.affaires; BEGIN IF NOT public.user_has_cap(_cap) THEN RAISE EXCEPTION 'Droit métier insuffisant'; END IF; SELECT * INTO a FROM affaires WHERE id=_id AND archived_at IS NULL; IF NOT FOUND OR NOT (public.user_cap_scope(_cap)='all' OR (public.user_cap_scope(_cap)='own' AND a.charge_affaires_id=auth.uid()) OR public.user_has_affaire_access(_id)) THEN RAISE EXCEPTION 'Accès affaire refusé'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.app_modifier_affaire(_id uuid,_patch jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE k text; sets text:=''; result jsonb; BEGIN PERFORM public.app_assert_affaire_write(_id,'section.affaires'); IF _patch ? 'dessinateur_id' AND _patch->>'dessinateur_id' IS NOT NULL AND NOT EXISTS(SELECT 1 FROM affaires WHERE id=_id AND numero ~ '^6[0-9]{3}$') THEN RAISE EXCEPTION 'Dessinateur réservé aux 6XXX'; END IF; IF _patch ? 'statut_opportunite' THEN PERFORM public.app_assert_affaire_write(_id,'action.edit_opportunite'); IF _patch->>'statut_opportunite' NOT IN ('a_faire','envoye','perdu') THEN RAISE EXCEPTION 'Signature interdite'; END IF; END IF; IF _patch ? 'ca_estime_ht' AND (_patch->>'ca_estime_ht')::numeric<0 THEN RAISE EXCEPTION 'Montant invalide'; END IF; IF jsonb_typeof(_patch)<>'object' OR _patch='{}'::jsonb THEN RAISE EXCEPTION 'Modification vide'; END IF; FOR k IN SELECT jsonb_object_keys(_patch) LOOP IF k NOT IN ('nom','notes','lieu','date_montage','date_demontage','date_evenement_debut','date_evenement_fin','date_pat','typologie_future','ca_estime_ht','charge_affaires_id','chef_projet_id','dessinateur_id','statut','statut_opportunite','contact_site_nom','contact_site_tel','montage_nb_techniciens','montage_travail_nuit','montage_nb_semi','montage_nb_20m3','montage_nature_prestation','montage_notes','client_id','opportunite_source','client_contact_id','client','taille') THEN RAISE EXCEPTION 'Champ interdit: %',k; END IF; sets:=sets || CASE WHEN sets='' THEN '' ELSE ',' END || format('%I=p.%I',k,k); END LOOP; EXECUTE format('UPDATE public.affaires t SET %s FROM jsonb_populate_record(NULL::public.affaires,$1) p WHERE t.id=$2 RETURNING jsonb_build_object(''id'',t.id)',sets) INTO result USING _patch,_id; IF result IS NULL THEN RAISE EXCEPTION 'Modification refusée par les droits'; END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.app_modifier_etape_logistique(_id uuid,_patch jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE k text; sets text:=''; result jsonb; e public.affaire_etapes_logistiques; d date; f date; BEGIN SELECT * INTO e FROM affaire_etapes_logistiques WHERE id=_id; PERFORM public.app_assert_affaire_write(e.affaire_id,'logistique.etape.edit'); d:=CASE WHEN _patch ? 'date_debut' THEN (_patch->>'date_debut')::date ELSE e.date_debut END; f:=CASE WHEN _patch ? 'date_fin' THEN (_patch->>'date_fin')::date ELSE e.date_fin END; IF d IS NULL OR f<d THEN RAISE EXCEPTION 'Dates invalides'; END IF; IF jsonb_typeof(_patch)<>'object' OR _patch='{}'::jsonb THEN RAISE EXCEPTION 'Modification vide'; END IF; FOR k IN SELECT jsonb_object_keys(_patch) LOOP IF k NOT IN ('type','sens','date_debut','date_fin','heure_debut','heure_fin','horaire_libre','lieu_libre','nb_personnes','responsable','vehicule_id','immatriculation_libre','acces','note','commentaire_equipe','statut') THEN RAISE EXCEPTION 'Champ interdit: %',k; END IF; sets:=sets || CASE WHEN sets='' THEN '' ELSE ',' END || format('%I=p.%I',k,k); END LOOP; EXECUTE format('UPDATE public.affaire_etapes_logistiques t SET %s FROM jsonb_populate_record(NULL::public.affaire_etapes_logistiques,$1) p WHERE t.id=$2 RETURNING jsonb_build_object(''id'',t.id)',sets) INTO result USING _patch,_id; IF result IS NULL THEN RAISE EXCEPTION 'Modification refusée par les droits'; END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.deplacer_etape_logistique(_etape_id uuid,_nouveau_debut date,_nouvelle_fin date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE e public.affaire_etapes_logistiques; f date; BEGIN SELECT * INTO e FROM affaire_etapes_logistiques WHERE id=_etape_id; IF NOT FOUND THEN RAISE EXCEPTION 'Étape introuvable'; END IF; f:=COALESCE(_nouvelle_fin,CASE WHEN e.date_fin IS NOT NULL THEN _nouveau_debut+(e.date_fin-e.date_debut) END); RETURN app_modifier_etape_logistique(_etape_id,jsonb_build_object('date_debut',_nouveau_debut,'date_fin',f)); END $$;
CREATE OR REPLACE FUNCTION public.app_creer_etape_logistique(_payload jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE r public.affaire_etapes_logistiques; k text; result jsonb; BEGIN PERFORM app_assert_affaire_write((_payload->>'affaire_id')::uuid,'logistique.etape.edit'); FOR k IN SELECT jsonb_object_keys(_payload) LOOP IF k NOT IN ('affaire_id','type','sens','date_debut','date_fin','heure_debut','heure_fin','horaire_libre','lieu_libre','nb_personnes','responsable','vehicule_id','immatriculation_libre','acces','note','commentaire_equipe','statut') THEN RAISE EXCEPTION 'Champ interdit'; END IF; END LOOP; r:=jsonb_populate_record(NULL::public.affaire_etapes_logistiques,_payload); IF r.date_debut IS NULL OR r.date_fin<r.date_debut THEN RAISE EXCEPTION 'Dates invalides'; END IF; INSERT INTO affaire_etapes_logistiques(affaire_id,type,sens,date_debut,date_fin,heure_debut,heure_fin,horaire_libre,lieu_libre,nb_personnes,responsable,vehicule_id,immatriculation_libre,acces,note,commentaire_equipe,origine,statut,created_by) VALUES(r.affaire_id,r.type,r.sens,r.date_debut,r.date_fin,r.heure_debut,r.heure_fin,r.horaire_libre,r.lieu_libre,r.nb_personnes,r.responsable,r.vehicule_id,r.immatriculation_libre,r.acces,r.note,r.commentaire_equipe,'manuel','valide',auth.uid()) RETURNING jsonb_build_object('id',id,'affaire_id',affaire_id) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.app_ajouter_action_opportunite(_affaire_id uuid,_type public.opp_action_type,_note text,_echeance date DEFAULT NULL) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE result jsonb; BEGIN PERFORM app_assert_affaire_write(_affaire_id,'action.edit_opportunite'); IF NOT EXISTS(SELECT 1 FROM affaires WHERE id=_affaire_id AND phase='opportunite') THEN RAISE EXCEPTION 'Opportunité requise'; END IF; IF length(trim(_note)) NOT BETWEEN 1 AND 2000 THEN RAISE EXCEPTION 'Note invalide'; END IF; INSERT INTO opportunite_actions(affaire_id,type,texte,auteur_id,prochaine_action_due_le) VALUES(_affaire_id,_type,_note,auth.uid(),_echeance) RETURNING jsonb_build_object('id',id,'affaire_id',affaire_id) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.app_ajouter_note_chantier(_affaire_id uuid,_texte text) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE result jsonb; BEGIN PERFORM app_assert_affaire_write(_affaire_id,'section.affaires'); IF length(trim(_texte)) NOT BETWEEN 1 AND 5000 THEN RAISE EXCEPTION 'Note invalide'; END IF; INSERT INTO affaire_commentaires(affaire_id,author_id,body) VALUES(_affaire_id,auth.uid(),_texte) RETURNING jsonb_build_object('id',id,'affaire_id',affaire_id) INTO result; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.app_creer_opportunite_client(_p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY INVOKER SET search_path=public AS $$ DECLARE c public.clients; a uuid; contact_id uuid; patch jsonb; BEGIN IF NOT user_has_cap('action.create_opportunite') THEN RAISE EXCEPTION 'Droit création insuffisant'; END IF; IF _p->>'client_id' IS NOT NULL THEN SELECT * INTO c FROM clients WHERE id=(_p->>'client_id')::uuid AND actif; ELSE SELECT * INTO c FROM clients WHERE lower(trim(nom))=lower(trim(_p->>'client_nom')) AND actif ORDER BY id LIMIT 1; END IF; IF c.id IS NULL THEN IF COALESCE((_p->>'creer_client')::boolean,false)=false THEN RAISE EXCEPTION 'Client inconnu: confirmer creer_client=true dans un nouvel aperçu'; END IF; INSERT INTO clients(nom,created_by) VALUES(_p->>'client_nom',auth.uid()) RETURNING * INTO c; END IF; a:=create_opportunite(c.nom,_p->>'intitule','9000',COALESCE((_p->>'charge_affaires_id')::uuid,auth.uid()),'petit',CURRENT_DATE,_p->>'description'); patch:=jsonb_build_object('client_id',c.id,'lieu',_p->>'lieu','date_montage',_p->>'date_montage','date_demontage',_p->>'date_demontage','date_evenement_debut',_p->>'date_evenement','typologie_future',_p->>'typologie_future','ca_estime_ht',_p->'ca_estime_ht','opportunite_source',_p->'source'); IF _p ? 'contact' THEN INSERT INTO client_contacts(client_id,nom,email,telephone,created_by) VALUES(c.id,_p->'contact'->>'nom',_p->'contact'->>'email',_p->'contact'->>'telephone',auth.uid()) RETURNING id INTO contact_id; patch:=patch || jsonb_build_object('client_contact_id',contact_id); END IF; PERFORM app_modifier_affaire(a,patch); RETURN (SELECT jsonb_build_object('id',id,'affaire_id',id,'numero',numero,'client_id',client_id) FROM affaires WHERE id=a); END $$;
REVOKE ALL ON FUNCTION app_assert_affaire_write(uuid,text),app_modifier_affaire(uuid,jsonb),app_modifier_etape_logistique(uuid,jsonb),deplacer_etape_logistique(uuid,date,date),app_creer_etape_logistique(jsonb),app_ajouter_action_opportunite(uuid,public.opp_action_type,text,date),app_ajouter_note_chantier(uuid,text),app_creer_opportunite_client(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION app_assert_affaire_write(uuid,text),app_modifier_affaire(uuid,jsonb),app_modifier_etape_logistique(uuid,jsonb),deplacer_etape_logistique(uuid,date,date),app_creer_etape_logistique(jsonb),app_ajouter_action_opportunite(uuid,public.opp_action_type,text,date),app_ajouter_note_chantier(uuid,text),app_creer_opportunite_client(jsonb) TO authenticated;